  function renderHotspots(){const host=$('lab-hotspots'),canvas=$('lab-canvas');if(closed||!host||!scene?.getHotspots||!canvas.getBoundingClientRect)return;const rect=canvas.getBoundingClientRect(),points=scene.getHotspots(),used=[];for(const point of points){let b=hotspotButtons.get(point.operation);if(!b){b=button(hotspotNames[point.operation]??'Instrument',()=>{if(point.operation==='atlas')setStation('atlas');else operations?.open(point.operation);});b.className='lab-hotspot';host.append(b);hotspotButtons.set(point.operation,b);}let x=rect.left+point.x-48,y=rect.top+point.y-18;const width=window?.innerWidth??rect.width,height=window?.innerHeight??rect.height;let visible=navigationMode==='walk'&&point.visible&&x>8&&x<width-114&&y>85&&y<height-(width<=900?157:138)&&$('lab-ops')?.hidden!==false&&$('lab-notebook')?.hidden!==false;const guide=$('lab-journey')?.getBoundingClientRect?.();if(guide&&x<guide.right+4&&x+110>guide.left&&y<guide.bottom+4&&y+30>guide.top)visible=false;const views=document.querySelector?.('.lab-stations')?.getBoundingClientRect?.();if(views&&x<views.right&&x+110>views.left&&y<views.bottom&&y+30>views.top)visible=false;for(let attempt=0;visible&&attempt<4&&used.some(p=>Math.abs(p.x-x)<112&&Math.abs(p.y-y)<34);attempt++)y+=34;if(y>height-(width<=900?157:138))visible=false;for(const selector of ['.lab-modebar','.lab-movement','.lab-specimen-hud','.lab-reagent-tray','.lab-help','.lab-status','.lab-scene-label','.lab-room-heading','.lab-atlas-controls']){const panel=document.querySelector?.(selector),bounds=panel?.getBoundingClientRect?.();if(bounds&&bounds.width>0&&x<bounds.right&&x+110>bounds.left&&y<bounds.bottom&&y+30>bounds.top)visible=false;}b.hidden=!visible;if(visible){b.style.left=`${Math.round(x)}px`;b.style.top=`${Math.round(y)}px`;used.push({x,y});}}}
